def __post_init__(self) -> None:
    if not isinstance(self.timeout, (int, float)) or self.timeout <= 0:
        raise ValueError("timeout must be a positive number.")
    if isinstance(self.max_retries, bool) or not isinstance(self.max_retries, int) or self.max_retries < 0:
        raise ValueError("max_retries must be a non-negative integer.")

    api_key = self.api_key if self.api_key is not None else os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("Set OPENAI_API_KEY to an OpenAI API key.")

    parsed_url = urllib.parse.urlparse(self.base_url)
    host = (parsed_url.hostname or "").lower()
    is_local_http = parsed_url.scheme == "http" and host in {"localhost", "127.0.0.1", "::1"}
    if parsed_url.scheme not in {"https", "http"} or (parsed_url.scheme == "http" and not is_local_http):
        raise ValueError("base_url must use HTTPS, or HTTP only for a local test server.")
    if not parsed_url.path.strip("/"):
        raise ValueError("base_url must include the API version path (normally /v1).")

    object.__setattr__(self, "api_key", api_key)

